window.MOTORBIKE_SEARCH = [{"title": "Il negozio", "url": "negozio.html", "text": "Il negozio Motorbike Vercelli"}, {"title": "Moto", "url": "moto.html", "text": "Moto Motorbike Vercelli"}, {"title": "Caschi", "url": "caschi.html", "text": "Caschi Motorbike Vercelli"}, {"title": "Abbigliamento", "url": "abbigliamento.html", "text": "Abbigliamento Motorbike Vercelli"}, {"title": "Interfoni", "url": "interfoni.html", "text": "Interfoni Motorbike Vercelli"}, {"title": "Cross", "url": "cross.html", "text": "Cross Motorbike Vercelli"}, {"title": "Accessori", "url": "accessori.html", "text": "Accessori Motorbike Vercelli"}, {"title": "Officina", "url": "officina.html", "text": "Officina Motorbike Vercelli"}, {"title": "Aquile Vercellesi", "url": "club.html", "text": "Aquile Vercellesi Motorbike Vercelli"}, {"title": "Contatti", "url": "contatti.html", "text": "Contatti Motorbike Vercelli"}, {"title": "Integrali", "url": "caschi-integrali.html", "text": "Caschi Integrali Per strada, turismo e guida sportiva. Confronta forme, materiali e ventilazione, poi prova la taglia con noi. Airoh, Grex, HJC, LS2 e Nolan sono tra i marchi del reparto integrali. Confronta la calzata e verifica con noi la disponibilità del singolo modello."}, {"title": "Modulari", "url": "caschi-modulari.html", "text": "Caschi Modulari Una mentoniera apribile per chi cerca versatilità nei viaggi e negli spostamenti di ogni giorno. Il reparto comprende caschi modulari in policarbonato, fibre composite e carbonio. Vieni a confrontare peso, meccanismo di apertura e calzata."}, {"title": "Jet", "url": "caschi-jet.html", "text": "Caschi Jet Caschi aperti e compatti da confrontare per i tuoi tragitti urbani e in scooter. Nel reparto trovi caschi jet e demi jet. Porta con te le tue esigenze di ingombro e di comfort: vediamo insieme quale modello provarci."}, {"title": "Crossover", "url": "caschi-crossover.html", "text": "Caschi Crossover Modelli versatili con frontino e visiera: una scelta da esplorare se alterni percorsi diversi. I caschi crossover del reparto permettono, in base al modello, di cambiare configurazione di frontino e visiera. Confrontali pensando alle strade che percorri."}, {"title": "Off-road", "url": "caschi-off-road.html", "text": "Caschi Off-road Il reparto dedicato a cross ed enduro, con caschi da abbinare al resto dell’equipaggiamento. Per il casco off-road, la prova va fatta insieme agli accessori che utilizzi. Porta la maschera, se ne hai già una, e confronta la calzata in negozio."}, {"title": "Giacche", "url": "abbigliamento-giacche.html", "text": "Abbigliamento Giacche Tessuto e pelle, capi estivi, invernali e per la mezza stagione. Il reparto giacche comprende proposte estive, invernali, di mezza stagione e quattro stagioni. Spidi e Ixon sono tra i marchi di abbigliamento trattati."}, {"title": "Pantaloni e jeans", "url": "abbigliamento-pantaloni.html", "text": "Abbigliamento Pantaloni e jeans Pantaloni tecnici e jeans moto: materiali e vestibilità da provare in camerino. In negozio trovi pantaloni tecnici e jeans pensati per la moto. Il taglio e la posizione delle protezioni vanno valutati anche piegando le gambe come in sella."}, {"title": "Guanti", "url": "abbigliamento-guanti.html", "text": "Abbigliamento Guanti Estivi, invernali, di mezza stagione e racing. Provali pensando ai tuoi comandi. Il reparto comprende guanti per diverse stagioni e utilizzi, anche racing. Confronta mobilità delle dita, lunghezza e chiusura prima di scegliere."}, {"title": "Scarpe", "url": "abbigliamento-scarpe.html", "text": "Abbigliamento Scarpe Calzature dal taglio urbano e tecnico per i tragitti di tutti i giorni. Sneakers moto e scarpe basse si affiancano ai modelli più tecnici. Vieni con le calze che usi abitualmente per confrontare taglia e comfort."}, {"title": "Stivali", "url": "abbigliamento-stivali.html", "text": "Abbigliamento Stivali Sport, turismo e adventure: trova la calzata adatta alla tua posizione di guida. Gli stivali si scelgono anche in funzione di moto e percorso. In negozio puoi confrontare altezza, chiusure e flessibilità."}, {"title": "Tute", "url": "abbigliamento-tute.html", "text": "Abbigliamento Tute Intere e divisibili, da provare per la guida sportiva. Il reparto presenta tute in pelle intere e a due pezzi. La prova serve a valutare come il capo si adatta alla tua posizione di guida."}, {"title": "Accessori e ricambi", "url": "accessori-accessori-vari.html", "text": "Accessori Accessori e ricambi Navigatori, action cam e componenti da abbinare alla tua moto. Marca, modello e anno aiutano a individuare accessori e ricambi compatibili. Scrivici cosa cerchi o porta il componente in negozio."}, {"title": "Lubrificanti", "url": "accessori-lubrificanti.html", "text": "Accessori Lubrificanti Prodotti per la manutenzione e la cura della moto. Motul ed Elf sono tra i prodotti disponibili per la manutenzione. Per scegliere il prodotto adatto, porta le indicazioni del manuale della tua moto."}, {"title": "Pneumatici", "url": "accessori-pneumatici.html", "text": "Accessori Pneumatici Gomme per utilizzi diversi, con servizio di cambio pneumatici in officina. In negozio puoi chiedere informazioni sugli pneumatici; l’officina è attrezzata con smontagomme. Concorda il cambio indicando moto e misure."}, {"title": "Scarichi", "url": "accessori-scarichi.html", "text": "Accessori Scarichi Informazioni su scarichi e compatibilità, partendo dal tuo modello. Per uno scarico servono riferimenti precisi della moto e del componente. Contattaci per verificare proposta e disponibilità."}, {"title": "Cardo", "url": "interfoni-cardo.html", "text": "Interfoni Cardo Scopri le proposte Cardo e confrontale con il tuo casco e il tuo gruppo. Esplora le proposte Cardo, compresa la famiglia Freecom. Chiedi in negozio i modelli attuali e verifica la compatibilità con i dispositivi che usate."}, {"title": "SMART HJC", "url": "interfoni-hjc.html", "text": "Interfoni SMART HJC Sistemi di comunicazione da verificare con il modello HJC che utilizzi. Confronta i sistemi SMART HJC partendo dal tuo casco. Indica il modello completo: l’abbinamento si verifica sul prodotto specifico."}, {"title": "Interphone", "url": "interfoni-interphone.html", "text": "Interfoni Interphone Una famiglia di sistemi da confrontare per i tuoi tragitti e le tue uscite. Esplora la famiglia U-COM e le proposte Interphone. Per conoscere la gamma attuale e gli abbinamenti, parla con il negozio."}, {"title": "Midland", "url": "interfoni-midland.html", "text": "Interfoni Midland Soluzioni di comunicazione per chi parte in coppia o con gli amici. Confronta le proposte Midland, comprese le famiglie Rush e BT. Verifica con il negozio la soluzione adatta al gruppo e ai caschi utilizzati."}, {"title": "Sena", "url": "interfoni-sena.html", "text": "Interfoni Sena Confronta le proposte Sena per comunicazione e collegamento ai tuoi dispositivi. Esplora le famiglie Sena, inclusa la serie 50. Modello, funzioni e disponibilità attuali si verificano direttamente in negozio."}, {"title": "N-Com", "url": "interfoni-n-com.html", "text": "Interfoni N-Com Parti dal modello del casco per chiedere informazioni sul sistema di comunicazione. Per le proposte N-Com, comunicaci il modello preciso del casco. Verifichiamo insieme il sistema compatibile e la disponibilità."}, {"title": "Tagliandi e cambio pneumatici", "url": "officina.html#richiesta", "text": "officina tagliando manutenzione gomme ricambi appuntamento"}];